Q: System.Text.Json: How do I specify a custom name for an enum value? A: <p>Update:</p>
<p>Starting in .NET 9, you can customize the names of individual enum members for types that are serialized as strings. To customize an enum member name, annotate it with the <a href="https://learn.microsoft.com/en-us/dotnet/api/system.text.json.serialization.jsonstringenummembernameattribute" rel="nofollow noreferrer">JsonStringEnumMemberName attribute</a>. See <a href="https://learn.microsoft.com/dotnet/standard/serialization/system-text-json/customize-properties#custom-enum-member-names" rel="nofollow noreferrer">Custom enum member names</a> for more information.</p>
<hr />
<p>For .NET 5.0 or greater ,you can add a JsonConverter</p>
<pre><code>public class EnumDescriptionJsonConverter : JsonConverter&lt;ValueType&gt;
{
    /// &lt;inheritdoc/&gt;
    public override bool CanConvert(Type typeToConvert)
    {
        return typeToConvert.IsEnum || typeToConvert.IsGenericType &amp;&amp; typeToConvert.GenericTypeArguments.Length == 1 &amp;&amp; typeToConvert.GenericTypeArguments[0].IsEnum;
    }
    /// &lt;inheritdoc/&gt;
    public override ValueType Read(ref Utf8JsonReader reader, Type typeToConvert, JsonSerializerOptions options)
    {
        throw new NotImplementedException();
    }
    /// &lt;inheritdoc/&gt;
    public override void Write(Utf8JsonWriter writer, ValueType value, JsonSerializerOptions options)
    {
        if (value == null)
            writer.WriteNullValue();
        else
            writer.WriteStringValue(GetDescription((value as Enum)!));
    }
    /// &lt;summary&gt;
    /// Get description
    /// &lt;/summary&gt;
    /// &lt;param name=&quot;source&quot;&gt;&lt;/param&gt;
    /// &lt;returns&gt;&lt;/returns&gt;
    static string GetDescription(Enum source)
    {
        System.Reflection.FieldInfo fi = source.GetType().GetField(source.ToString());
        if (fi == null) return source.ToString();
        System.ComponentModel.DescriptionAttribute[] attributes = (System.ComponentModel.DescriptionAttribute[])fi.GetCustomAttributes(typeof(System.ComponentModel.DescriptionAttribute), false);

        if (attributes != null &amp;&amp; attributes.Length &gt; 0) return attributes[0].Description;
        else return source.ToString();
    }
}
</code></pre>
<p>The model for serialization</p>
<pre class="lang-cs prettyprint-override"><code>        public class MyClass
        {
            public MyEnum MyEnumWith0 { get; set; }
            public MyEnum MyEnumWith1 { get; set; }
            public MyEnum? NullableMyEnumWith0 { get; set; }
            public MyEnum? NullableMyEnumWith1 { get; set; }
            public MyEnum? NullableMyEnumWithNull { get; set; }
            public MyEnum? NullableMyEnumWith2 { get; set; }
        }

        public enum MyEnum
        {
            [Description(&quot;Description&quot;)]
            Key = 1,
            NoDescriptionKey = 2,
        }
</code></pre>
<p>Used and Test</p>
<pre class="lang-cs prettyprint-override"><code>    JsonSerializerOptions jsonSerializerOptions = new JsonSerializerOptions() { WriteIndented = true };
    Assert.Equal(@&quot;{
      &quot;&quot;MyEnumWith0&quot;&quot;: 0,
      &quot;&quot;MyEnumWith1&quot;&quot;: 1,
      &quot;&quot;NullableMyEnumWith0&quot;&quot;: 0,
      &quot;&quot;NullableMyEnumWith1&quot;&quot;: 1,
      &quot;&quot;NullableMyEnumWithNull&quot;&quot;: null,
      &quot;&quot;NullableMyEnumWith2&quot;&quot;: 2
    }&quot;, JsonSerializer.Serialize(value, jsonSerializerOptions));
        jsonSerializerOptions = new JsonSerializerOptions() { WriteIndented = true };
        jsonSerializerOptions.Converters.Add(new JsonStringEnumConverter());
        Assert.Equal(@&quot;{
      &quot;&quot;MyEnumWith0&quot;&quot;: 0,
      &quot;&quot;MyEnumWith1&quot;&quot;: &quot;&quot;Key&quot;&quot;,
      &quot;&quot;NullableMyEnumWith0&quot;&quot;: 0,
      &quot;&quot;NullableMyEnumWith1&quot;&quot;: &quot;&quot;Key&quot;&quot;,
      &quot;&quot;NullableMyEnumWithNull&quot;&quot;: null,
      &quot;&quot;NullableMyEnumWith2&quot;&quot;: &quot;&quot;NoDescriptionKey&quot;&quot;
    }&quot;, JsonSerializer.Serialize(value, jsonSerializerOptions));
        jsonSerializerOptions = new JsonSerializerOptions() { WriteIndented = true };
        jsonSerializerOptions.Converters.Add(new EnumDescriptionJsonConverter());
        Assert.Equal(@&quot;{
      &quot;&quot;MyEnumWith0&quot;&quot;: &quot;&quot;0&quot;&quot;,
      &quot;&quot;MyEnumWith1&quot;&quot;: &quot;&quot;Description&quot;&quot;,
      &quot;&quot;NullableMyEnumWith0&quot;&quot;: &quot;&quot;0&quot;&quot;,
      &quot;&quot;NullableMyEnumWith1&quot;&quot;: &quot;&quot;Description&quot;&quot;,
      &quot;&quot;NullableMyEnumWithNull&quot;&quot;: null,
      &quot;&quot;NullableMyEnumWith2&quot;&quot;: &quot;&quot;NoDescriptionKey&quot;&quot;
    }&quot;, JsonSerializer.Serialize(value, jsonSerializerOptions));
</code></pre>
<p>This converter is only available for serialization</p>

Q: How to get the new value of a textarea input field on paste? A: <p>Stumbled onto this question so many years later looking for the same solution, and at least on Firefox 146 the following seems to work with the below HTML</p>
<p><code>&lt;textarea id=&quot;paste_dump&quot; onchange=&quot;readPaste(event)&quot; onpaste=&quot;readPaste(event)&quot;&gt;</code></p>
<p>And the javascript function as:</p>
<pre><code>function readPaste(e) {
    if(e.clipboardData) {
    //  onpaste triggers before value is updated, so pull data directly from clipboard
        var pasteText = e.clipboardData.getData('text/plain');
    } else {
    //  if onpaste doesn't work, at least clicking out (onchange) will still make the function do the stuff
        var pasteText = document.getElementById(&quot;paste_dump&quot;).value;
    }
    // Do Stuff
}
</code></pre>
<p>This seems to at least check the event object for the presence of clipboard data (which to the best of my knowledge should only exist on pasting in this case) and if that is absent due to either manual typing into the input or a failure of onpaste support, taking focus off the input element should still trigger the function and use what is then currently in the value attribute.</p>

Q: How to fix missing dependency warning when using useEffect React Hook A: <p>If you want to read the latest values of certain state and/or props in an effect <strong>without having the effect run again when those values change</strong>, you may be looking for an Effect Event, which is supported since React 19.2.0. To define an Effect Event, call the <a href="https://react.dev/reference/react/useEffectEvent" rel="nofollow noreferrer"><code>useEffectEvent</code></a> hook, passing in a callback. This hook is intended to extract non-reactive logic out of effects and allows the callback to always access the latest values of state and props at the time it is invoked. The React ESLint rules also know about Effect Events and do not require them to be added to dependency arrays.</p>
<p>As an example, consider a component with two states, <code>a</code> and <code>b</code>. We want to log the current value of <code>b</code> every time <code>a</code> changes. If we use a regular effect that depends only on <code>a</code>, it would violate the <a href="https://react.dev/reference/eslint-plugin-react-hooks/lints/exhaustive-deps" rel="nofollow noreferrer">react-hooks/exhaustive-deps</a> rule as the effect also accesses <code>b</code>. But if we add <code>b</code> to the dependency array, we will get extraneous logs for the same value of <code>a</code> when the value of <code>b</code> changes, which is undesirable. <code>useEffectEvent</code> can solve this problem with no linter warnings like so:</p>
<pre><code>import { useState, useEffect, useEffectEvent } from &quot;react&quot;;
// ...
const [a, setA] = useState(initialA);
const [b, setB] = useState(initialB);

const log = useEffectEvent((newA) =&gt; {
    console.log(&quot;a has changed to&quot;, newA, &quot;and the value of b at this time is&quot;, b);
});

useEffect(() =&gt; {
    log(a); // reads current value of b without having the effect depend on it
}, [a]); // only depends on a
</code></pre>
